import { FilterBar, KpiRow, PageHeader, type ActiveFilter, type FilterField } from '@gntik-ai/blocks';
import { Download, Plus } from '@gntik-ai/icons';
import {
  Avatar,
  Drawer,
  DrawerBody,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
  HStack,
  KanbanBoard,
  LiveAnnouncer,
  Page,
  SimpleSelect,
  Stack,
  StatusTag,
  Text,
  Timestamp,
  useAnnounce,
  type BreadcrumbItem,
  type KanbanColumn,
  type KanbanMove,
} from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  applyVisibleMove,
  formatAge,
  matchesTriage,
  triageBreadcrumbs,
  triageColumns,
  triageFilterFields,
  triageKpis,
  triageNow,
  triageSeverities,
  type TriageIncident,
} from './data';

export interface IncidentBoardProps {
  title: string;
  description: string;
  /** Initial columns (stages) and incident cards. */
  defaultColumns: KanbanColumn<TriageIncident>[];
  filterFields: FilterField[];
  defaultFilters: ActiveFilter[];
  /** Clock for the card ages (epoch ms). */
  now: number;
  /** Fires after a card moves (drag, keyboard or the drawer's status select), in full-board indices. */
  onMove: (move: KanbanMove, columns: KanbanColumn<TriageIncident>[]) => void;
  /** Initially open incident (details drawer). */
  defaultOpenId: string | null;
  onDeclare: () => void;
  onExport: () => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  shell: Omit<ConsoleShellProps, 'children'>;
}

type Handlers = 'onMove' | 'onDeclare' | 'onExport';
type BoardProps = Omit<IncidentBoardProps, 'breadcrumbs' | 'currentHref' | 'shell' | Handlers> & Partial<Pick<IncidentBoardProps, Handlers>>;

function IncidentCard({ incident, now }: { incident: TriageIncident; now: number }) {
  return (
    <span className="grid gap-2">
      <span className="text-[13px] leading-5 font-medium text-foreground">{incident.title}</span>
      <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
        <StatusTag status={incident.severity} statuses={triageSeverities} size="sm" />
        <span className="font-mono text-[11px] text-muted-foreground">{incident.id}</span>
      </span>
      <span className="flex items-center justify-between gap-2 text-[12px] text-muted-foreground">
        <span className="flex min-w-0 items-center gap-1.5">
          <Avatar size="xs" name={incident.owner} aria-hidden />
          <span className="truncate">{incident.owner}</span>
        </span>
        <span className="font-mono tabular-nums">
          <span className="sr-only">Age </span>
          {formatAge(incident.openedAt, now)}
        </span>
      </span>
    </span>
  );
}

function IncidentBoard({ title, description, defaultColumns, filterFields, defaultFilters, now, onMove, defaultOpenId, onDeclare, onExport }: BoardProps) {
  const announce = useAnnounce();
  const [columns, setColumns] = useState(defaultColumns);
  const [query, setQuery] = useState('');
  const [filters, setFilters] = useState<ActiveFilter[]>(defaultFilters);
  const [openId, setOpenId] = useState<string | null>(defaultOpenId);

  const visible = columns.map((c) => ({ ...c, cards: c.cards.filter((i) => matchesTriage(i, query, filters)) }));
  const shown = visible.reduce((n, c) => n + c.cards.length, 0);
  const openColumn = columns.find((c) => c.cards.some((i) => i.id === openId));
  const open = openColumn?.cards.find((i) => i.id === openId);

  const commit = (next: KanbanColumn<TriageIncident>[], move: KanbanMove) => {
    setColumns(next);
    onMove?.(move, next);
  };

  const moveFromDrawer = (incident: TriageIncident, toColumnId: string) => {
    const from = columns.find((c) => c.cards.some((i) => i.id === incident.id));
    const to = columns.find((c) => c.id === toColumnId);
    if (!from || !to || from.id === to.id) return;
    const result = applyVisibleMove(columns, columns, {
      cardId: incident.id,
      fromColumnId: from.id,
      fromIndex: from.cards.findIndex((i) => i.id === incident.id),
      toColumnId: to.id,
      toIndex: to.cards.length,
    });
    commit(result.columns, result.move);
    announce(`${incident.title} moved to ${to.title}.`);
  };

  return (
    <>
      <Page
        width="full"
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description={description}
            status=""
            meta={[]}
            tabs={null}
            actions={[
              { label: 'Export', icon: Download, variant: 'secondary', onClick: onExport },
              { label: 'Declare incident', icon: Plus, variant: 'primary', onClick: onDeclare },
            ]}
          />
        }
      >
        <Stack gap={5}>
          <KpiRow items={triageKpis(columns)} variant="strip" showTrends={false} label="Incident summary" />
          <FilterBar
            fields={filterFields}
            views={[]}
            query={query}
            onQueryChange={setQuery}
            filters={filters}
            onFiltersChange={setFilters}
            placeholder="Search id, title, service or owner…"
            resultCount={shown}
          />
          <KanbanBoard<TriageIncident>
            label="Incidents by stage"
            headingLevel={2}
            emptyText="No incidents"
            columns={visible}
            onMove={(move) => {
              const result = applyVisibleMove(columns, visible, move);
              commit(result.columns, result.move);
            }}
            getCardLabel={(i) => `${i.id} ${i.title}, ${triageSeverities[i.severity].label}`}
            onCardOpen={(i) => setOpenId(i.id)}
            renderCard={(i) => <IncidentCard incident={i} now={now} />}
          />
        </Stack>
      </Page>
      <Drawer open={open != null} onOpenChange={(next) => !next && setOpenId(null)}>
        <DrawerContent size="md">
          {open && openColumn && (
            <>
              <DrawerHeader>
                <DrawerTitle>{open.title}</DrawerTitle>
                <DrawerDescription>
                  {open.id} · {open.service}
                </DrawerDescription>
              </DrawerHeader>
              <DrawerBody>
                <Stack gap={5}>
                  <HStack gap={2} wrap>
                    <StatusTag status={open.severity} statuses={triageSeverities} />
                    <Text as="span" variant="caption" tone="muted">
                      Open for {formatAge(open.openedAt, now)}
                    </Text>
                  </HStack>
                  <Text variant="supporting">{open.summary}</Text>
                  <dl className="grid grid-cols-[7rem_1fr] items-center gap-x-4 gap-y-3 text-[13px]">
                    <dt className="text-muted-foreground">Stage</dt>
                    <dd>
                      <SimpleSelect
                        aria-label="Stage"
                        size="sm"
                        items={columns.map((c) => ({ value: c.id, label: c.title }))}
                        value={openColumn.id}
                        onValueChange={(v) => v && moveFromDrawer(open, v)}
                        className="w-44"
                      />
                    </dd>
                    <dt className="text-muted-foreground">Owner</dt>
                    <dd className="flex items-center gap-2 text-foreground">
                      <Avatar size="xs" name={open.owner} aria-hidden />
                      {open.owner}
                    </dd>
                    <dt className="text-muted-foreground">Service</dt>
                    <dd className="font-mono text-foreground">{open.service}</dd>
                    <dt className="text-muted-foreground">Declared</dt>
                    <dd className="text-foreground">
                      <Timestamp value={open.openedAt} format="absolute" tooltip={false} />
                    </dd>
                  </dl>
                </Stack>
              </DrawerBody>
            </>
          )}
        </DrawerContent>
      </Drawer>
    </>
  );
}

/** Incident triage board: KPI summary, FilterBar and a KanbanBoard by stage with keyboard moves and a details Drawer. */
export default function IncidentBoardPage(props: Partial<IncidentBoardProps>) {
  const {
    title = 'Incident board',
    description = 'Triage incidents by stage. Drag a card, or focus it and press Space to pick it up; Enter opens the details.',
    defaultColumns = triageColumns,
    filterFields = triageFilterFields,
    defaultFilters = [],
    now = triageNow,
    onMove,
    defaultOpenId = null,
    onDeclare,
    onExport,
    breadcrumbs = triageBreadcrumbs,
    currentHref = '/incidents',
    shell,
  } = props;
  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <LiveAnnouncer>
        <IncidentBoard
          title={title}
          description={description}
          defaultColumns={defaultColumns}
          filterFields={filterFields}
          defaultFilters={defaultFilters}
          now={now}
          onMove={onMove}
          defaultOpenId={defaultOpenId}
          onDeclare={onDeclare}
          onExport={onExport}
        />
      </LiveAnnouncer>
    </ConsoleShell>
  );
}

import type { ActiveFilter, FilterField, KpiItem } from '@gntik-ai/blocks';
import { moveKanbanCard, type BreadcrumbItem, type KanbanCard, type KanbanColumn, type KanbanMove, type StatusDefinition } from '@gntik-ai/ui';

export type TriageSeverity = 'sev1' | 'sev2' | 'sev3';
export type TriageStage = 'triage' | 'investigating' | 'mitigated' | 'resolved';

/** One incident card on the triage board. */
export interface TriageIncident extends KanbanCard {
  severity: TriageSeverity;
  service: string;
  owner: string;
  /** Epoch ms when the incident was declared. */
  openedAt: number;
  summary: string;
}

export const triageSeverities: Record<TriageSeverity, StatusDefinition> = {
  sev1: { label: 'SEV1', tone: 'destructive' },
  sev2: { label: 'SEV2', tone: 'warning' },
  sev3: { label: 'SEV3', tone: 'info' },
};

export const triageStageLabels: Record<TriageStage, string> = {
  triage: 'Triage',
  investigating: 'Investigating',
  mitigated: 'Mitigated',
  resolved: 'Resolved',
};

export const UNASSIGNED = 'Unassigned';

/** Compact age ("45m", "3h 10m", "2d 4h") of an incident opened at `openedAt`. */
export function formatAge(openedAt: number, now: number): string {
  const minutes = Math.max(0, Math.floor((now - openedAt) / 60_000));
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return minutes % 60 ? `${hours}h ${minutes % 60}m` : `${hours}h`;
  const days = Math.floor(hours / 24);
  return hours % 24 ? `${days}d ${hours % 24}h` : `${days}d`;
}

const MIN = 60_000;
/** Fixture clock: ages are computed against this instant. */
export const triageNow = Date.now();
const ago = (minutes: number) => triageNow - minutes * MIN;

const incident = (
  id: string,
  title: string,
  severity: TriageSeverity,
  service: string,
  owner: string,
  minutesAgo: number,
  summary: string,
): TriageIncident => ({ id, title, severity, service, owner, openedAt: ago(minutesAgo), summary });

export const triageColumns: KanbanColumn<TriageIncident>[] = [
  {
    id: 'triage',
    title: triageStageLabels.triage,
    cards: [
      incident('INC-3120', 'Checkout latency above 2 s', 'sev1', 'payments-api', UNASSIGNED, 12, 'p95 latency on checkout doubled after the 14:00 deploy; error budget burning at 6×.'),
      incident('INC-3118', 'Search results missing new items', 'sev3', 'search-index', UNASSIGNED, 95, 'Items created in the last hour do not appear in search; indexing lag is growing.'),
    ],
  },
  {
    id: 'investigating',
    title: triageStageLabels.investigating,
    cards: [
      incident('INC-3115', 'Elevated 5xx on the API gateway', 'sev1', 'api-gateway', 'Ada Park', 48, 'One availability zone returns 502s for 4% of requests; traffic shift in progress.'),
      incident('INC-3111', 'Webhook deliveries delayed', 'sev2', 'webhooks', 'Linus Ortega', 190, 'Delivery queue depth at 40k; workers restart on an out-of-memory error.'),
    ],
  },
  {
    id: 'mitigated',
    title: triageStageLabels.mitigated,
    cards: [incident('INC-3104', 'Sign-in emails bouncing', 'sev2', 'auth-service', 'Grace Kim', 420, 'Mail provider rate limit hit; traffic moved to the backup sender.')],
  },
  {
    id: 'resolved',
    title: triageStageLabels.resolved,
    cards: [
      incident('INC-3097', 'Dashboard charts not loading', 'sev3', 'analytics', 'Mei Chen', 1500, 'A stale CDN asset broke the chart bundle; cache purged and a fix deployed.'),
      incident('INC-3092', 'Billing worker stuck on retries', 'sev2', 'billing-worker', 'Ada Park', 2900, 'A malformed invoice blocked the queue; it was skipped and the parser fixed.'),
    ],
  },
];

const services = [...new Set(triageColumns.flatMap((c) => c.cards.map((i) => i.service)))].sort();
const owners = [...new Set(triageColumns.flatMap((c) => c.cards.map((i) => i.owner)))].sort();

export const triageFilterFields: FilterField[] = [
  { id: 'severity', label: 'Severity', options: Object.values(triageSeverities).map((s) => s.label) },
  { id: 'service', label: 'Service', options: services },
  { id: 'owner', label: 'Owner', options: owners },
];

/** Filter value of an incident for a FilterBar field id. */
export function triageFieldValue(i: TriageIncident, field: string): string | undefined {
  if (field === 'severity') return triageSeverities[i.severity].label;
  if (field === 'service') return i.service;
  if (field === 'owner') return i.owner;
  return undefined;
}

/** True when the incident matches the search text and every filtered field (OR within a field). */
export function matchesTriage(i: TriageIncident, query: string, filters: readonly ActiveFilter[]): boolean {
  const q = query.trim().toLowerCase();
  if (q && ![i.id, i.title, i.service, i.owner].some((v) => v.toLowerCase().includes(q))) return false;
  const byField = new Map<string, string[]>();
  for (const f of filters) byField.set(f.field, [...(byField.get(f.field) ?? []), f.value]);
  return [...byField].every(([field, values]) => values.includes(triageFieldValue(i, field) ?? ''));
}

/** KPI tiles computed from the board. */
export function triageKpis(columns: KanbanColumn<TriageIncident>[]): KpiItem[] {
  const cards = (id: string) => columns.find((c) => c.id === id)?.cards ?? [];
  const open = columns.filter((c) => c.id !== 'resolved').flatMap((c) => c.cards);
  return [
    { id: 'open', label: 'Open incidents', value: String(open.length) },
    { id: 'sev1', label: 'Open SEV1', value: String(open.filter((i) => i.severity === 'sev1').length) },
    { id: 'unassigned', label: 'Unassigned', value: String(open.filter((i) => i.owner === UNASSIGNED).length) },
    { id: 'resolved', label: 'Resolved', value: String(cards('resolved').length) },
  ];
}

export const triageBreadcrumbs: BreadcrumbItem[] = [{ label: 'Acme Industries', href: '/overview' }, { label: 'Incidents' }];

/**
 * Maps a move made on the filtered (visible) board onto the full board: the card lands before the
 * visible card it was dropped on, or after the last visible one. Returns the new columns and the
 * move in full-board indices.
 */
export function applyVisibleMove<T extends KanbanCard>(
  full: KanbanColumn<T>[],
  visible: KanbanColumn<T>[],
  move: KanbanMove,
): { columns: KanbanColumn<T>[]; move: KanbanMove } {
  const cardsOf = (cols: KanbanColumn<T>[], id: string) => cols.find((c) => c.id === id)?.cards ?? [];
  const fromIndex = cardsOf(full, move.fromColumnId).findIndex((c) => c.id === move.cardId);
  const destVisible = cardsOf(visible, move.toColumnId).filter((c) => c.id !== move.cardId);
  const destFull = cardsOf(full, move.toColumnId).filter((c) => c.id !== move.cardId);
  const anchor = destVisible[move.toIndex];
  const last = destVisible[destVisible.length - 1];
  const toIndex = anchor ? destFull.findIndex((c) => c.id === anchor.id) : last ? destFull.findIndex((c) => c.id === last.id) + 1 : destFull.length;
  const fullMove = { ...move, fromIndex, toIndex };
  return { columns: moveKanbanCard(full, fullMove), move: fullMove };
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
